        public void NewGroup(){if(app.Store.Active.Groups.Count>=200)throw new InvalidOperationException("Limite de 200 grupos por perfil.");string n=UI.Ask(this,"Nome do novo grupo","Novo grupo");if(n==null)return;var g=new Group{Name=n.Substring(0,Math.Min(120,n.Length))};app.FreePosition(g);app.Store.Active.Groups.Add(g);app.Store.Save();app.RebuildDocks();Select(g.Id);}
        public void RenameGroup(Group g){string n=UI.Ask(this,"Nome do grupo",g.Name);if(n!=null){g.Name=n.Substring(0,Math.Min(120,n.Length));app.Store.Save();app.RebuildDocks();Refresh();}}
        public void DeleteGroup(Group g){if(UI.Confirm(this,"Remover o grupo “"+g.Name+"”? Os arquivos originais serão preservados e os atalhos arquivados serão devolvidos à área de trabalho.")){app.Store.RemoveGroup(g);app.RebuildDocks();Select("home");}}
