            Combo(form,"Estilo de expansão",Store.Layouts,g.Layout,delegate(string s){g.Layout=s;SaveGroup();});
            Combo(form,"Ao clicar duas vezes",new[]{"Nenhuma","Abrir todos","Gerenciador"},g.DoubleAction,delegate(string s){g.DoubleAction=s;SaveGroup();});content.Children.Add(UI.Card(form,new Thickness(22)));
            var list=UI.Stack();var listhead=new DockPanel();var add=UI.Row(UI.Button("+ Arquivos",delegate{AddFiles(g);},true),UI.Button("+ Pasta",delegate{AddFolder(g);}),UI.Button("+ Link",delegate{AddLink(g);}));DockPanel.SetDock(add,Dock.Right);listhead.Children.Add(add);listhead.Children.Add(UI.Text("Atalhos ("+g.Entries.Count+")",17,UI.Ink));list.Children.Add(listhead);
