            var entries=new StackPanel();Action populate=delegate{entries.Children.Clear();foreach(var entry in g.Entries.Where(e=>e.Name.IndexOf(filter,StringComparison.OrdinalIgnoreCase)>=0||e.Target.IndexOf(filter,StringComparison.OrdinalIgnoreCase)>=0).ToList())AddEntryRow(entries,g,entry);if(g.Entries.Count==0){var empty=UI.Stack(UI.Text("Solte seus atalhos aqui",17,UI.Ink),UI.Text("Aplicativos, documentos, pastas e links. Os originais permanecem no lugar no modo Cópia.",12,UI.Muted));empty.Margin=new Thickness(10,30,10,30);entries.Children.Add(empty);}};search.TextChanged+=delegate{filter=search.Text;populate();};populate();list.Children.Add(entries);
            var drop=UI.Card(list,new Thickness(22));drop.AllowDrop=true;drop.DragOver+=delegate(object s,DragEventArgs e){e.Effects=e.Data.GetDataPresent(DataFormats.FileDrop)?DragDropEffects.Copy:DragDropEffects.None;e.Handled=true;};drop.Drop+=delegate(object s,DragEventArgs e){app.Drop(g,e);};content.Children.Add(drop);
