            var actions=UI.Row(UI.Button("↗",delegate{app.Launch(entry);}),UI.Button("↑",delegate{Move(g,entry,-1);}),UI.Button("↓",delegate{Move(g,entry,1);}),UI.Button("⋯",delegate{EntryOptions(g,entry);}),UI.Button("×",delegate{app.Store.Remove(g,entry);app.RebuildDocks();Refresh();}));foreach(Button b in actions.Children){b.Padding=new Thickness(9,6,9,6);b.MinHeight=28;b.Margin=new Thickness(4,0,0,0);}Grid.SetColumn(actions,2);row.Children.Add(actions);list.Children.Add(row);
