        void Move(Group g,Entry e,int delta){int old=g.Entries.IndexOf(e),i=old+delta;if(i<0||i>=g.Entries.Count)return;g.Entries.RemoveAt(old);g.Entries.Insert(i,e);app.Store.Save();app.RebuildDocks();Refresh();}
        void EntryOptions(Group g,Entry e){var c=new ContextMenu();Action<string,Action> add=delegate(string text,Action a){var m=new MenuItem{Header=text};m.Click+=delegate{try{a();}catch(Exception ex){app.Error(ex);}};c.Items.Add(m);};add("Renomear atalho…",delegate{string n=UI.Ask(this,"Nome do atalho",e.Name);if(n!=null){e.Name=n.Substring(0,Math.Min(260,n.Length));app.Store.Save();app.RebuildDocks();Refresh();}});add("Abrir localização",delegate{Native.Reveal(e.Target);});add("Usar ícone no grupo",delegate{app.Store.UseIcon(g,e);app.RebuildDocks();Refresh();});add("Devolver à área de trabalho",delegate{app.ToDesktop(g,e);app.RebuildDocks();Refresh();});c.IsOpen=true;}
        public void AddFiles(Group g){var dialog=new OpenFileDialog{Title="Adicionar arquivos e aplicativos",Multiselect=true,CheckFileExists=true,Filter="Todos os arquivos|*.*"};if(dialog.ShowDialog(this)==true){int count=0;foreach(var path in dialog.FileNames)if(app.Store.Add(g,path,false)!=null)count++;app.RebuildDocks();Refresh();Notice(count+" atalho(s) adicionado(s).");}}
        void AddFolder(Group g){using(var d=new System.Windows.Forms.FolderBrowserDialog{Description="Escolha uma pasta para adicionar ao grupo",ShowNewFolderButton=false}){if(d.ShowDialog()==System.Windows.Forms.DialogResult.OK){app.Store.Add(g,d.SelectedPath,false);app.RebuildDocks();Refresh();}}}
        void AddLink(Group g){string url=UI.Ask(this,"Endereço do link (https://…)","https://");if(url==null)return;Uri uri;if(!Uri.TryCreate(url,UriKind.Absolute,out uri)||(uri.Scheme!="https"&&uri.Scheme!="http"))throw new InvalidOperationException("Informe um endereço http:// ou https:// válido.");app.Store.Add(g,url,false);app.RebuildDocks();Refresh();}
        void ChooseIcon(Group g){var d=new OpenFileDialog{Title="Escolher ícone",Filter="Ícones e aplicativos|*.ico;*.png;*.jpg;*.exe;*.lnk|Todos os arquivos|*.*"};if(d.ShowDialog(this)==true){string src=d.FileName,ext=Path.GetExtension(src).ToLowerInvariant();if(ext==".png"||ext==".jpg"||ext==".ico"||ext==".lnk"){string relative=Path.Combine("atalhos","icone-"+Guid.NewGuid().ToString("N")+ext);File.Copy(src,app.Store.Local(relative));g.Icon=relative;}else g.Icon=src;SaveGroup();}}
        void ImportDesktop(){
            var w=new Window{Title="Importar atalhos da área de trabalho",Owner=this,Width=530,Height=560,WindowStartupLocation=WindowStartupLocation.CenterOwner,Background=UI.Back,Foreground=UI.Ink,FontFamily=FontFamily};
            var checkboxes=new List<CheckBox>();var stack=UI.Stack();var pick=new ComboBox{Margin=new Thickness(0,12,0,16),Height=32};foreach(var g in app.Store.Active.Groups)pick.Items.Add(new ComboBoxItem{Content=g.Name,Tag=g});if(pick.Items.Count==0){NewGroup();return;}pick.SelectedIndex=0;
            stack.Children.Add(UI.Text("Escolha os atalhos e o grupo de destino.",15,UI.Ink));stack.Children.Add(UI.Text("Esta importação mantém os originais na área de trabalho.",12,UI.Muted));stack.Children.Add(pick);
            string[] dirs={Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),Environment.GetFolderPath(Environment.SpecialFolder.CommonDesktopDirectory)};
            foreach(string dir in dirs.Distinct()){if(!Directory.Exists(dir))continue;foreach(string file in Directory.GetFiles(dir).Where(p=>new[]{".lnk",".url"}.Contains(Path.GetExtension(p).ToLowerInvariant()))){var cb=new CheckBox{Content=Path.GetFileNameWithoutExtension(file),Tag=file,Foreground=UI.Ink,Margin=new Thickness(0,6,0,6)};checkboxes.Add(cb);stack.Children.Add(cb);}}
            if(checkboxes.Count==0)stack.Children.Add(UI.Text("Nenhum atalho .lnk ou .url encontrado na área de trabalho.",13,UI.Muted));
            var layout=new DockPanel{Margin=new Thickness(22)};var button=UI.Button("Importar selecionados",delegate{try{Group g=(Group)((ComboBoxItem)pick.SelectedItem).Tag;foreach(var cb in checkboxes.Where(c=>c.IsChecked==true))app.Store.Add(g,(string)cb.Tag,false);app.RebuildDocks();w.Close();Select(g.Id);}catch(Exception ex){app.Error(ex);}},true);DockPanel.SetDock(button,Dock.Bottom);layout.Children.Add(button);layout.Children.Add(new ScrollViewer{Content=stack,VerticalScrollBarVisibility=ScrollBarVisibility.Auto});w.Content=layout;w.ShowDialog();
        }
        void Combo(StackPanel parent,string title,string[] values,string current,Action<string> change){var row=new Grid{Margin=new Thickness(0,18,0,0)};row.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});row.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(185)});row.Children.Add(UI.Text(title,12,UI.Ink));var c=new ComboBox{ItemsSource=values,SelectedItem=current,Height=30,FontSize=12};Grid.SetColumn(c,1);row.Children.Add(c);c.SelectionChanged+=delegate{if(c.SelectedItem!=null)try{change((string)c.SelectedItem);}catch(Exception ex){app.Error(ex);}};parent.Children.Add(row);}
