        void Profiles(){TitleBlock("Uma organização para cada momento.","Alterne entre trabalho, casa ou uma área de trabalho para apresentações.");content.Children.Add(UI.Row(UI.Button("+ Novo perfil",delegate{string n=UI.Ask(this,"Nome do perfil","Novo perfil");if(n!=null){if(app.Store.Data.Profiles.Count>=50)throw new InvalidOperationException("Limite de 50 perfis.");var p=new Profile{Name=n.Substring(0,Math.Min(120,n.Length))};app.Store.Data.Profiles.Add(p);app.Switch(p.Id);}},true),UI.Button("Duplicar perfil atual",delegate{string n=UI.Ask(this,"Nome da cópia",app.Store.Active.Name+" — cópia");if(n!=null){var p=app.Store.Clone(app.Store.Active,n.Substring(0,Math.Min(120,n.Length)));app.Switch(p.Id);}})));var gap=UI.Text("PERFIS DISPONÍVEIS",10,UI.Muted);gap.Margin=new Thickness(0,28,0,15);content.Children.Add(gap);foreach(var profile in app.Store.Data.Profiles.ToList()){Profile p=profile;var box=UI.Stack(UI.Text(p.Name+(p.Id==app.Store.Data.ActiveId?"  ● ATIVO":""),16,p.Id==app.Store.Data.ActiveId?UI.Accent:UI.Ink),UI.Text(p.Groups.Count+" grupos  ·  "+p.Groups.Sum(g=>g.Entries.Count)+" atalhos",12,UI.Muted));var actions=UI.Row(UI.Button("Ativar",delegate{app.Switch(p.Id);}),UI.Button("Renomear",delegate{string n=UI.Ask(this,"Nome do perfil",p.Name);if(n!=null){p.Name=n.Substring(0,Math.Min(120,n.Length));app.Store.Save();Refresh();app.BuildTray();}}));if(p.Id!=app.Store.Data.ActiveId)actions.Children.Add(UI.Button("Excluir",delegate{if(UI.Confirm(this,"Excluir o perfil “"+p.Name+"”? Os originais arquivados serão restaurados.")){foreach(var e in p.Groups.SelectMany(g=>g.Entries))app.Store.Restore(e);app.Store.Data.Profiles.Remove(p);app.Store.Save();Refresh();app.BuildTray();}}));actions.Margin=new Thickness(0,16,0,0);box.Children.Add(actions);content.Children.Add(UI.Card(box,new Thickness(22)));}content.Children.Add(UI.Text("Duplicar um perfil mantém os atalhos e as preferências, sem duplicar a responsabilidade pelos originais arquivados.",12,UI.Muted));}
        void Export(){var d=new SaveFileDialog{Title="Exportar backup",Filter="Backup Zilda (*.zip)|*.zip",FileName="Zilda-backup-"+DateTime.Now.ToString("yyyy-MM-dd")+".zip"};if(d.ShowDialog(this)==true){app.Store.Backup(d.FileName);Notice("Backup salvo.");}}
        void Import(){var d=new OpenFileDialog{Title="Restaurar backup",Filter="Backup Zilda (*.zip)|*.zip"};if(d.ShowDialog(this)==true&&UI.Confirm(this,"Substituir os perfis atuais pelo backup? Uma cópia de segurança da configuração atual será salva antes da troca.")){app.Store.Import(d.FileName);app.RebuildDocks();app.BuildTray();Select("home");Notice("Backup restaurado.");}}
        void About(){TitleBlock("Zilda Organizadora","Versão 1.0.0  ·  Feito para simplificar sua área de trabalho.");var body=UI.Stack(UI.Text("Comece em poucos passos",18,UI.Ink),UI.Text("1. Crie um grupo e adicione arquivos, pastas ou links.\n\n2. Encontre o ícone do grupo na área de trabalho. Passe o mouse ou clique para abrir.\n\n3. Arraste o grupo para mudar sua posição. Clique em um atalho para abrir.\n\n4. Para voltar aqui, dê dois cliques no ícone da Zilda perto do relógio. O × do gerenciador mantém os grupos ativos. Para encerrar, use Sair no menu desse ícone.",13,UI.Muted));content.Children.Add(UI.Card(body,new Thickness(24)));content.Children.Add(UI.Card(UI.Stack(UI.Text("Seus dados ficam com você",17,UI.Ink),UI.Text("Funciona sem conta e sem conexão. Não envia telemetria e não baixa atualizações automaticamente. Crie backups nas Configurações. Documentos e aplicativos são referências aos locais originais; se forem movidos, adicione-os novamente.",13,UI.Muted)),new Thickness(24)));content.Children.Add(UI.Card(UI.Stack(UI.Text("Integração com o Windows",17,UI.Ink),UI.Text("Os grupos são janelas anexadas à área de trabalho do Explorer. A grade de alinhamento é própria. O aplicativo não reposiciona ícones nativos. O tema se aplica aos painéis de atalhos; o gerenciador mantém sua aparência escura.\n\nAtalho global: Ctrl + Alt + Z abre o gerenciador, quando disponível.\n\nReconstrução independente inspirada no DeskRipple. Não inclui código, ícones proprietários, licenças ou serviços do produto original.",13,UI.Muted)),new Thickness(24)));content.Children.Add(UI.Row(UI.Button("Abrir dados e logs",delegate{Native.Shell(app.Store.Root);}),UI.Button("Exportar backup…",Export),UI.Button("Encerrar Zilda",delegate{app.Exit();})));
        }
